        setHoveredNode(d);
        d3.select(event.currentTarget).select('circle')
          .transition()
          .duration(200)
          .attr('r', d.id === artifactId ? 30 : 25);
      })
      .on('mouseleave', (event, d) => {
        setHoveredNode(null);
        d3.select(event.currentTarget).select('circle')
          .transition()
          .duration(200)
          .attr('r', d.id === artifactId ? 25 : 20);
      })
