(async () => {
      setError(null);
      setLoading(true);
      try {
        if (id) {
          logDebug("ProjectDetail: Starting to load project details");
          setProgress({
            loading: true,
            percent: 5,
            step: "Loading project...",
          });
          const data = await loadProjectDetails();
          logDebug("ProjectDetail: Project data loaded:", data);
          if (!data) {
            throw new Error('Project not found');
          }
          // Load thresholds and initial history
          try {
            const h = await getQualityHistory({
              project_id: Number(id),
              limit: 20,
            });
            setHist(h.history || []);
          } catch {}
          try {
            logDebug("ProjectDetail: Loading tasks for project:", id);
            setProgress({
              loading: true,
              percent: 20,
              step: "Loading tasks...",
            });
            // Use paginated API for server-side pagination
            const response = await listTasksByProjectPaginated(Number(id), {
              skip: 0,
              limit: 25, // Initial page size
            });
            logDebug("ProjectDetail: Tasks loaded:", response.data?.length, "of", response.meta.total);
            if (response.data.length === 0 && lastRowsRef.current.length > 0) {
              setToast({
                open: true,
                type: "warning",
                msg: "No tasks returned from Jira; keeping cached data.",
              });
            } else {
              setRows(response.data);
              setTaskRowCount(response.meta.total);
              lastRowsRef.current = response.data;
            }
          } catch (e) {
            console.error("ProjectDetail: Failed to load tasks:", e);
          }
          try {
            setProgress({
              loading: true,
              percent: 35,
              step: "Analyzing risks...",
            });
            setRisks(await getRisks(Number(id)));
          } catch {}
          try {
            setProgress({
              loading: true,
              percent: 50,
              step: "Loading burndown...",
            });
            setBurndown(await getBurndown(Number(id)));
          } catch {}
          try {
            setProgress({
              loading: true,
              percent: 65,
              step: "Calculating velocity...",
            });
            const v = await getVelocity(Number(id));
            setVelocityAvg(v?.average_velocity || 0);
          } catch {}
          try {
            setProgress({
              loading: true,
              percent: 70,
              step: "Loading budget hours...",
            });
            const b = await getProjectBudgetHours(Number(id));
            setBudgetHours(b);
          } catch {}
          try {
            setProgress({
              loading: true,
              percent: 72,
              step: "Loading value metrics...",
            });
            const vm = await getProjectValueMetrics(Number(id));
            setValueMetrics(vm);
          } catch {}
          try {
            setProgress({
              loading: true,
              percent: 73,
              step: "Loading team members...",
            });
            const tm = await getTeamMembersActivity(Number(id));
            setTeamMembers(tm || []);
          } catch {}
          try {
            if (data?.jira_key) {
              setProgress({
                loading: true,
                percent: 75,
                step: "Loading boards...",
              });
              const b = await getBoardsForProject(data.jira_key);
              setBoards(b.boards || []);
              if ((b.boards || []).length) setBoardId(b.boards[0].id);
            }
          } catch {}
          try {
            setProgress({
              loading: true,
              percent: 85,
              step: "Loading sprints...",
            });
            const sp = await getProjectSprints(
              Number(id),
              10,
              typeof boardId === "number" ? boardId : undefined,
            );
            setSprints(sp.sprints || []);
            const active =
              (sp.sprints || []).find((s) => s.state === "active") ||
              (sp.sprints || [])[0];
            const activeSprintId = active?.sprint_id ?? active?.id;
            if (typeof activeSprintId === "number") {
              setSelectedSprint(activeSprintId);
              try {
                setProgress({
                  loading: true,
                  percent: 92,
                  step: "Loading sprint burndown...",
                });
                setSprintBurndown(await getSprintBurndown(activeSprintId));
              } catch {}
              try {
                setProgress({
                  loading: true,
                  percent: 95,
                  step: "Computing sprint quality...",
                });
                setSprintQuality(await getSprintQuality(activeSprintId));
              } catch {}
              try {
                setProgress({
                  loading: true,
                  percent: 98,
                  step: "Calculating sprint capacity...",
                });
                setSprintCapacity(await getSprintCapacity(activeSprintId));
              } catch {}
            }
          } catch (e) {
            console.error(e);
          }
          // Auto-sync if last sync older than 12h
          try {
            const lastSync = data?.meta?.last_sync_at
              ? new Date(data.meta.last_sync_at).getTime()
              : 0;
            const twelveHrs = 12 * 3600 * 1000;
            if (
              (!lastSync || Date.now() - lastSync > twelveHrs) &&
              !autoSyncTriedRef.current &&
              !autoSyncDisabledRef.current
            ) {
              autoSyncTriedRef.current = true;

              const runAutoSync = async () => {
                try {
                  const integ = await getIntegrationsStatus();
                  const ok = integ?.jira?.configured && integ?.jira?.has_token;
                  if (!ok) {
                    setToast({
                      open: true,
                      type: "warning",
                      msg: "Auto-sync skipped: Jira not configured or token missing",
                    });
                    return;
                  }

                  setToast({
                    open: true,
                    type: "info",
                    msg: "Auto-sync started (last sync stale)",
                  });
                  setSyncing(true);
                  setSyncProgress({
                    active: true,
                    percent: 5,
                    step: "Syncing with Jira...",
                  });
                  if (syncTimerRef.current) clearInterval(syncTimerRef.current);
                  syncTimerRef.current = setInterval(() => {
                    setSyncProgress((p) => ({
                      ...p,
                      percent: p.percent < 90 ? p.percent + 2 : 90,
                    }));
                  }, 300);

                  try {
                    await syncJiraProject(data.jira_key, { timeout: 10000 });
                  } catch (e) {
                    if (!timedOut(e)) throw e;
                  }

                  setSyncProgress((p) => ({
                    ...p,
                    step: "Applying updates...",
                  }));
                  // Use paginated API for polling after auto-sync
                  let taskTotal = 0;
                  try {
                    const response = await listTasksByProjectPaginated(Number(id), {
                      skip: taskPaginationModel.page * taskPaginationModel.pageSize,
                      limit: taskPaginationModel.pageSize,
                    });
                    taskTotal = response.meta.total;
                    if (taskTotal > 0) {
                      setRows(response.data);
                      setTaskRowCount(taskTotal);
                      lastRowsRef.current = response.data;
                    }
                  } catch (e) {
                    if (timedOut(e)) {
                      let attempts = 0;
                      const maxAttempts = 30;
                      await new Promise<void>((resolve) => {
                        const iv = setInterval(async () => {
                          attempts++;
                          try {
                            const response = await listTasksByProjectPaginated(Number(id), {
                              skip: taskPaginationModel.page * taskPaginationModel.pageSize,
                              limit: taskPaginationModel.pageSize,
                            });
                            taskTotal = response.meta.total;
                            if (taskTotal > 0) {
                              setRows(response.data);
                              setTaskRowCount(taskTotal);
                              lastRowsRef.current = response.data;
                            }
                          } catch {}
                          if (taskTotal > 0 || attempts >= maxAttempts) {
                            clearInterval(iv);
                            resolve();
                          }
                        }, 2000);
                      });
                    } else {
                      throw e;
                    }
                  }

                  if (taskTotal > 0) {
                    await loadProjectDetails(true);
                    setToast({
                      open: true,
                      type: "success",
                      msg: "Auto-sync completed",
                    });
                  } else {
                    setToast({
                      open: true,
                      type: "warning",
                      msg: "Auto-sync returned no tasks; previous data kept.",
                    });
                    autoSyncDisabledRef.current = true;
                  }
                  if (syncTimerRef.current) clearInterval(syncTimerRef.current);
                  syncTimerRef.current = null;
                  setSyncProgress({
                    active: false,
                    percent: 100,
                    step: "Sync complete",
                  });
                  setSyncing(false);
                } catch (e) {
                  if (syncTimerRef.current) clearInterval(syncTimerRef.current);
                  syncTimerRef.current = null;
                  setSyncing(false);
                  setSyncProgress({ active: false, percent: 0, step: "" });
                  setToast({
                    open: true,
                    type: "error",
                    msg: `Auto-sync failed: ${getErrorMessage(e, "Unknown error")}`,
                  });
                  try {
                    wsRef.current?.close();
                  } catch {}
                  clearIntegrationStatusCache();
                  autoSyncDisabledRef.current = true;
                } finally {
                  if (autoSyncTimeoutRef.current !== null) {
                    autoSyncTimeoutRef.current = null;
                  }
                }
              };

              if (autoSyncTimeoutRef.current !== null) {
                clearTimeout(autoSyncTimeoutRef.current);
              }
              autoSyncTimeoutRef.current = window.setTimeout(() => {
                runAutoSync().catch((err) =>
                  console.error("Auto-sync background error", err),
                );
              }, 0);
            }
          } catch (e) {
            if (syncTimerRef.current) clearInterval(syncTimerRef.current);
            syncTimerRef.current = null;
            setSyncing(false);
            setSyncProgress({ active: false, percent: 0, step: "" });
            try {
              wsRef.current?.close();
            } catch {}
            clearIntegrationStatusCache();
            autoSyncDisabledRef.current = true;
          }
        }
      } catch (e) {
        if (isDevelopment) {
          console.error('[ProjectDetail] Failed to load project', e);
        }
        setError(getErrorMessage(e, 'Failed to load project details'));
        setProject(null);
      } finally {
        setLoading(false);
        setProgress({ loading: false, percent: 100, step: "Ready" });
        setSyncing(false);
        setSyncProgress({ active: false, percent: 0, step: "" });
      }
    })

(async () => {
      try {
        if (autoSyncDisabledRef.current) return; // don't open WS if auto-sync disabled
        const integ = await getIntegrationsStatus();
        const ok = integ?.jira?.configured && integ?.jira?.has_token;
        if (!ok) return; // don't open WS if Jira not configured
        const proto = window.location.protocol === "https:" ? "wss" : "ws";
        const base = window.location.host;
        const ws = new WebSocket(`${proto}://${base}/api/v1/ws`);
        wsRef.current = ws;
        ws.onmessage = async (ev) => {
          try {
            const msg = JSON.parse(ev.data || "{}");
            if (
              msg?.type === "jira_sync_complete" &&
              typeof id === "string" &&
              Number(id) === Number(msg?.project_id)
            ) {
              // Reload current page with paginated API after sync
              await loadTasksPage();
              await loadProjectDetails(true);
              setToast({
                open: true,
                type: "success",
                msg: "Background sync completed",
              });
            } else if (
              msg?.type === "jira_sync_failed" &&
              typeof id === "string" &&
              Number(id) === Number(msg?.project_id)
            ) {
              autoSyncDisabledRef.current = true;
              const detail = typeof msg?.detail === "string" ? msg.detail : "";
              let message = "Jira sync failed";
              if (msg?.reason === "auth") {
                message = "Jira sync failed: access denied";
              } else if (msg?.reason === "unexpected") {
                message = "Jira sync failed: unexpected Jira response";
              } else if (msg?.reason === "empty") {
                message = "Jira sync failed: no issues returned";
              }
              setToast({
                open: true,
                type: "error",
                msg: detail ? `${message}: ${detail}` : message,
              });
            }
          } catch {}
        };
        ws.onclose = () => {
          if (!closed) wsRef.current = null;
        };
      } catch {}
    })

(teamMembers.length > 0
              ? teamMembers.map((m): TeamMemberDisplay => ({
                  name: m.assignee,
                  email: m.email ?? undefined,
                  active_tasks: m.active_tasks ?? m.count ?? 0,
                  last_activity: m.last_activity ?? null,
                  days_since_activity: m.days_since_activity ?? null,
                }))
              : Array.from(
                  new Map(
                    rows
                      .filter((r) => r.assignee_name)
                      .map((r) => [r.assignee_name, r] as const),
                  ).values(),
                ).map((r): TeamMemberDisplay => ({
                  name: r.assignee_name || '',
                  active_tasks: rows.filter((x) => x.assignee_name === r.assignee_name).length,
                  last_activity: null,
                  days_since_activity: null,
                }))
            ).map

(() => {
              const current = sprints.find(
                (s) => (s.sprint_id ?? s.id) === selectedSprint,
              );
              if (!current) return null;

              // Map backend fields to expected frontend fields with safe defaults
              const commitmentHours =
                current.commitment_hours ?? current.commitment ?? 0;
              const completedHours =
                current.completed_hours ?? current.completed ?? 0;
              const scopeAddedHours = current.scope_added_hours ?? 0;
              const predictabilityPct =
                current.predictability_pct ??
                (commitmentHours > 0
                  ? (completedHours / commitmentHours) * 100
                  : 0);
              const carryoverHours = current.carryover_hours ?? 0;

              // Forecast KPI
              let forecastLabel = "N/A";
              try {
                const startDate = current.start_date;
                const endDate = current.end_date;
                if (startDate && endDate) {
                  const sd = new Date(startDate).getTime();
                  const ed = new Date(endDate).getTime();
                  const now = Date.now();
                  const totalDays = Math.max(1, (ed - sd) / (1000 * 3600 * 24));
                  const elapsedDays = Math.max(
                    0,
                    Math.min(totalDays, (now - sd) / (1000 * 3600 * 24)),
                  );
                  const commit = Number(commitmentHours);
                  const completed = Number(completedHours);
                  const remaining = Math.max(commit - completed, 0);
                  const daysLeft = Math.max(0.1, totalDays - elapsedDays);
                  const paceNeeded = remaining / daysLeft;
                  const paceCurrent =
                    elapsedDays > 0 ? completed / elapsedDays : 0;
                  const onTrack =
                    paceCurrent + 0.01 >=
                    (commit / totalDays) * (elapsedDays / totalDays)
                      ? completed / commit >= elapsedDays / totalDays - 0.05
                      : completed / commit >= elapsedDays / totalDays - 0.05;
                  forecastLabel = `${onTrack ? "On track" : "At risk"} — need ${Math.round(paceNeeded * 10) / 10}h/day`;
                }
              } catch {}
              const cards = [
                {
                  title: "Commitment",
                  value: `${typeof commitmentHours === "number" ? commitmentHours.toFixed(1) : commitmentHours}h`,
                },
                {
                  title: "Completed",
                  value: `${typeof completedHours === "number" ? completedHours.toFixed(1) : completedHours}h`,
                },
                {
                  title: "Scope Change",
                  value: `${typeof scopeAddedHours === "number" ? scopeAddedHours.toFixed(1) : scopeAddedHours}h`,
                },
                {
                  title: "Predictability",
                  value: `${typeof predictabilityPct === "number" ? predictabilityPct.toFixed(1) : predictabilityPct}%`,
                },
                {
                  title: "Carryover",
                  value: `${typeof carryoverHours === "number" ? carryoverHours.toFixed(1) : carryoverHours}h`,
                },
                { title: "Forecast", value: forecastLabel },
              ];
              return cards.map((c, idx) => (
                <Grid item xs={12} sm={6} md={2} key={idx}>
                  <Card>
                    <CardContent>
                      <Typography color="textSecondary" gutterBottom>
                        {c.title}
                      </Typography>
                      <Typography variant="h5">{c.value}</Typography>
                    </CardContent>
                  </Card>
                </Grid>
              ));
            })

(() => {
                    const n = hist.length;
                    if (!n) return "N/A";
                    const passRatio =
                      hist.reduce((a, h) => a + ((h.passed ?? h.pass) ? 1 : 0), 0) / n;
                    const avgCov =
                      hist
                        .map((h) => h.line_coverage ?? 1)
                        .reduce((a, b) => a + b, 0) / n;
                    const score =
                      Math.round(passRatio * (avgCov || 1) * 1000) / 10;
                    return `${score}`;
                  })

(async () => {
      try {
        const { data } = await api.get("/v1/jira/projects", {
          signal: ctrl.signal,
        });
        setJiraProjects(data.projects || []);
      } catch (e: unknown) {
        const err = e as { code?: string };
        if (err.code === "ERR_CANCELED") return;
      }
    })

(async () => {
      const ps = await listProjects();
      setProjects(ps);
      if (ps.length) setProjectId(ps[0].id);
    })

(async () => {
      if (!projectId) return;
      try {
        setLoading(true);
        setProgress({ active: true, percent: 5, step: 'Loading Pull Requests...' });
        const pr = await listPullRequests({ project_id: Number(projectId), limit: 100 });
        setPRs(pr.pull_requests || []);
        setProgress({ active: true, percent: 35, step: 'Loading project thresholds...' });
        try {
          const p = await getProjectById(Number(projectId));
          const t = p.quality_thresholds || {};
          setThresholds({ min_line: t.min_line ?? 0.8, min_branch: t.min_branch ?? undefined });
        } catch {}
        // Preload gate status for each PR
        setProgress({ active: true, percent: 60, step: 'Evaluating current gate statuses...' });
        const gm: Record<number, QualityGateResult> = {};
        let done = 0;
        for (const item of (pr.pull_requests || [])) {
          try {
            const st = await getQualityGateStatus(item.number, Number(projectId));
            gm[item.number] = st;
          } catch {}
          done++;
          setProgress({ active: true, percent: 60 + Math.round((done / Math.max(1, pr.pull_requests.length)) * 35), step: `Evaluating gates... ${done}/${pr.pull_requests.length}` });
        }
        setGateMap(gm);
      } finally {
        setLoading(false);
        setProgress({ active: false, percent: 100, step: 'Ready' });
      }
    })

(async () => {
      try {
        const health = await getIntegrationsHealth();
        let info = health?.jira?.configured || health?.github ? 'Integrations OK' : 'Integrations: check settings';
        // Parse metrics for webhook activity
        const txt = await getMetricsText();
        const m = /webhook_received_total\{provider="github", event="([^"]+)"\} (\d+)/g;
        let total = 0; let match;
        while ((match = m.exec(txt)) !== null) { total += Number(match[2] || 0); }
        info = `GitHub Webhooks: ${total}`;
        setWebhookInfo(info);
      } catch {}
    })

